  const cps = Array.from(input)
  const len = cps.length
  let pos = 0
  let line = 1
  let col = 1

  function peek(offset = 0) {
    return cps[pos + offset]
  }

  function advance() {
    const c = cps[pos]
    pos++
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = Math.floor((col - 1) / 4) * 4 + 5
    } else {
      col++
    }
    return c
  }

  function fail(l, c, reason) {
    throw new LexError(l, c, reason)
  }

  function scanDigitRun(isDigit) {
    let count = 0
    let lastWasDigit = false
    while (pos < len) {
      const c = peek()
      if (isDigit(c)) {
        advance()
        count++
        lastWasDigit = true
      } else if (c === '_' && lastWasDigit && isDigit(peek(1))) {
        advance()
        lastWasDigit = false
      } else {
        break
      }
    }
    return count
  }

  function scanNumber() {
    const startLine = line
    const startCol = col
    const startPos = pos
    let prefixNoDigit = false

    const c0 = peek()
    const c1 = peek(1)
    if (c0 === '0' && (c1 === 'x' || c1 === 'X')) {
      advance()
      advance()
      const n = scanDigitRun(isHexDigit)
      if (n === 0) prefixNoDigit = true
    } else if (c0 === '0' && (c1 === 'b' || c1 === 'B')) {
      advance()
      advance()
      const n = scanDigitRun(isBinDigit)
