import { scan, LexError } from './lexer.js'

const STAT_ORDER = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

async function readStdin() {
  const chunks = []
  for await (const chunk of process.stdin) {
    chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk))
  }
  return Buffer.concat(chunks).toString('utf8')
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
    return
  }

  const mode = args[0]
  const input = await readStdin()

  let tokens
  try {
    tokens = scan(input)
  } catch (e) {
    if (e instanceof LexError) {
      process.stderr.write(`error: ${e.line}:${e.col}: ${e.reason}\n`)
      process.exit(2)
      return
    }
    throw e
  }

  let out = ''
  if (mode === 'tokens') {
    for (const t of tokens) {
      out += `${t.line}:${t.col} ${t.kind} ${t.text}\n`
    }
  } else {
    const counts = { ident: 0, keyword: 0, number: 0, punct: 0, rawstring: 0, string: 0 }
    for (const t of tokens) counts[t.kind]++
    let total = 0
    for (const k of STAT_ORDER) {
      out += `${k} ${counts[k]}\n`
      total += counts[k]
    }
    out += `total ${total}\n`
  }

  process.stdout.write(out)
  process.exit(0)
}

